#include <string>

#include <sstream>

using namespace std;

bool isOperator(string token) {

    return token == "+" || token == "-" || 

           token == "*" || token == "/";

}

int applyOp(int a, int b, char op) {

    switch(op) {

        case '+': return a + b;

        case '-': return a - b;

        case '*': return a * b;

        case '/': return a / b;

    }

    return 0;

}

int evaluatePostfix(string postfix) {

    stack<int> st;

    stringstream ss(postfix);

    string token;



    while (ss >> token) {

        if (isOperator(token)) {

            int b = st.top(); st.pop();

            int a = st.top(); st.pop();

            st.push(applyOp(a, b, token[0]));

        } else {

            st.push(stoi(token));

        }

    }

    return st.top();

}

